return $input.all().map(item => {
  const raw = item.json.response ?? "";
  const origin = $('Code in JavaScript').first().json;

  const myName = "Sam";

  const finalEmail = raw.replace(/\[(My Name|Your Name)\]/gi, myName);

  const objetMatch = finalEmail.match(/Subject\s*[:：]\s*(.+)/i);
  const objet = objetMatch ? objetMatch[1].trim() : "";

  const email = origin.destination;

  const lignes = finalEmail.split(/\r?\n/);
  const indexObjet = lignes.findIndex(l => /Subject\s*[:：]/i.test(l));

  const contenu = lignes
    .slice(indexObjet + 1)
    .join("\n")
    .trim();

  return {
    json: { objet, contenu, email }
  };
});
